// Minimal PNG decoder for the canvas inspector (8-bit, non-interlaced).
// Playwright screenshots use PNG colour types 2/6; palette/greyscale inputs are
// expanded to RGBA so the inspector's pixel metrics work unchanged.
const zlib = require('node:zlib');

function readSync(buffer) {
  if (!Buffer.isBuffer(buffer) || buffer.length < 8) throw new Error('pngjs shim: not a PNG buffer');
  let offset = 8, width = 0, height = 0, bitDepth = 0, colorType = 0, interlace = 0;
  const idat = [];
  while (offset < buffer.length) {
    const length = buffer.readUInt32BE(offset); offset += 4;
    const type = buffer.toString('ascii', offset, offset + 4); offset += 4;
    const data = buffer.subarray(offset, offset + length); offset += length + 4;
    if (type === 'IHDR') {
      width = data.readUInt32BE(0); height = data.readUInt32BE(4);
      bitDepth = data[8]; colorType = data[9]; interlace = data[12];
    } else if (type === 'IDAT') idat.push(data);
    else if (type === 'IEND') break;
  }
  if (bitDepth !== 8 || interlace !== 0) throw new Error(`pngjs shim: unsupported PNG (depth ${bitDepth}, interlace ${interlace})`);
  const channels = { 0: 1, 2: 3, 4: 2, 6: 4 }[colorType];
  if (!channels) throw new Error(`pngjs shim: unsupported colour type ${colorType}`);
  const raw = zlib.inflateSync(Buffer.concat(idat));
  const stride = width * channels, output = Buffer.alloc(width * height * 4);
  let previous = Buffer.alloc(stride), cursor = 0;
  for (let y = 0; y < height; y++) {
    const filter = raw[cursor++];
    const line = Buffer.from(raw.subarray(cursor, cursor + stride)); cursor += stride;
    for (let x = 0; x < stride; x++) {
      const left = x >= channels ? line[x - channels] : 0;
      const up = previous[x];
      const upLeft = x >= channels ? previous[x - channels] : 0;
      let value = line[x];
      if (filter === 1) value += left;
      else if (filter === 2) value += up;
      else if (filter === 3) value += (left + up) >> 1;
      else if (filter === 4) {
        const p = left + up - upLeft, pa = Math.abs(p - left), pb = Math.abs(p - up), pc = Math.abs(p - upLeft);
        value += pa <= pb && pa <= pc ? left : pb <= pc ? up : upLeft;
      } else if (filter !== 0) throw new Error(`pngjs shim: bad filter ${filter}`);
      line[x] = value & 0xff;
    }
    for (let x = 0; x < width; x++) {
      const source = x * channels, target = (y * width + x) * 4;
      if (channels >= 3) { output[target] = line[source]; output[target + 1] = line[source + 1]; output[target + 2] = line[source + 2]; }
      else { output[target] = output[target + 1] = output[target + 2] = line[source]; output[target + 3] = 255; }
      output[target + 3] = channels === 4 ? line[source + 3] : channels === 2 ? line[source + 1] : 255;
    }
    previous = line;
  }
  return { width, height, data: output };
}

module.exports = { PNG: { sync: { read: readSync } } };
